import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { copyFileSync } from 'node:fs'

// src/<name>/index.d.ts is hand-written (notify and panel are plain JS/JSX, not compiled from TS),
// so it isn't generated by the build — just copied into dist/<name>/ alongside the bundle.
function copyTypes(name) {
  return {
    name: 'copy-types',
    closeBundle() {
      copyFileSync(`src/${name}/index.d.ts`, `dist/${name}/index.d.ts`)
    },
  }
}

// `aw-kit/notify` and `aw-kit/panel` each need a build; `npm run build` runs vite twice
// (default mode = notify, `--mode panel` = panel), each into its own dist/<name>/ so neither empties the other.
// `aw-kit/eslint-rules` and the bin are plain Node ESM served straight from src/ and bin/, so they are not part of any bundle.
export default defineConfig(({ mode }) => {
  const name = mode === 'panel' ? 'panel' : 'notify'
  return {
    plugins: [react(), copyTypes(name)],
    build: {
      outDir: `dist/${name}`,
      lib: {
        entry: `src/${name}/index.js`,
        formats: ['es'],
        fileName: () => 'index.js',
      },
      rollupOptions: {
        external: ['react', 'react-dom', 'react/jsx-runtime'],
        output: {
          assetFileNames: (assetInfo) =>
            assetInfo.name?.endsWith('.css') ? 'style.css' : assetInfo.name,
        },
      },
      cssCodeSplit: false, // force single dist/<name>/style.css instead of per-chunk splitting
    },
  }
})
